import base64, hashlib, json, os, socket, struct, sys, time, urllib.parse, requests

def recv_exact(s,n):
    b=b''
    while len(b)<n:
        c=s.recv(n-len(b))
        if not c: raise EOFError
        b+=c
    return b

def read_frame(s):
    b1,b2=recv_exact(s,2)
    ln=b2&0x7f
    if ln==126: ln=struct.unpack('"'!H'"',recv_exact(s,2))[0]
    elif ln==127: ln=struct.unpack('"'!Q'"',recv_exact(s,8))[0]
    masked=b2>>7
    mask=recv_exact(s,4) if masked else b''
    data=recv_exact(s,ln)
    if masked: data=bytes(data[i]"'^mask[i%4] for i in range(ln))
    return data.decode('"'utf-8', 'replace')

def send_frame(s, txt):
    data=txt.encode(); head=bytearray([0x81]); ln=len(data)
    if ln<126: head.append(0x80|ln)
    elif ln<65536: head.append(0x80|126); head+=struct.pack('"'!H'"',ln)
    else: head.append(0x80|127); head+=struct.pack('"'!Q'"',ln)
    mask=os.urandom(4); head+=mask
    s.sendall(bytes(head)+bytes(data[i]"'^mask[i%4] for i in range(ln)))

